import assert from "node:assert/strict";
import { decideWhatsApp as d } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g5-2/bot.mjs";

const NOW = new Date("2026-01-01T12:00:00Z");
const S = Math.floor(NOW.getTime() / 1000);            // Meta-style seconds
const ago = (h) => String(S - h * 3600);               // inbound h hours ago
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: ago(1), ...over });

const cases = [
  // allowed
  [{ type: "text", contact: c() }, NOW, { allowed: true, reason: null }],
  [{ type: "text", contact: c({ lastInboundTimestamp: ago(23.9) }) }, NOW, { allowed: true, reason: null }],
  [{ type: "template", contact: c({ lastInboundTimestamp: null }) }, NOW, { allowed: true, reason: null }],
  [{ type: "template", contact: c({ lastInboundTimestamp: ago(500) }) }, NOW, { allowed: true, reason: null }],
  // window closed
  [{ type: "text", contact: c({ lastInboundTimestamp: ago(24) }) }, NOW, { allowed: false, reason: "outside_service_window" }],
  [{ type: "text", contact: c({ lastInboundTimestamp: ago(25) }) }, NOW, { allowed: false, reason: "outside_service_window" }],
  [{ type: "text", contact: c({ lastInboundTimestamp: null }) }, NOW, { allowed: false, reason: "outside_service_window" }],
  // opt-in
  [{ type: "template", contact: c({ optedIn: false }) }, NOW, { allowed: false, reason: "not_opted_in" }],
  [{ type: "text", contact: c({ optedIn: false }) }, NOW, { allowed: false, reason: "not_opted_in" }],
  [{ type: "text", contact: c({ optedIn: "yes" }) }, NOW, { allowed: false, reason: "not_opted_in" }],
  // timestamp misread
  [{ type: "text", contact: c({ lastInboundTimestamp: String(S * 1000) }) }, NOW, { allowed: false, reason: "invalid_inbound_timestamp" }],
  [{ type: "text", contact: c({ lastInboundTimestamp: "abc" }) }, NOW, { allowed: false, reason: "invalid_inbound_timestamp" }],
  [{ type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, NOW, { allowed: false, reason: "invalid_inbound_timestamp" }],
  // malformed input
  [{ type: "sms", contact: c() }, NOW, { allowed: false, reason: "unknown_message_type" }],
  [{ type: "text" }, NOW, { allowed: false, reason: "invalid_message" }],
  [null, NOW, { allowed: false, reason: "invalid_message" }],
  [{ type: "text", contact: c() }, new Date("x"), { allowed: false, reason: "invalid_now" }],
];

cases.forEach(([m, now, want], i) => {
  assert.deepEqual(d(m, now), want, `case ${i}`);
});
console.log(`ok: ${cases.length} cases`);

// The spec example: 1767272400 is 2026-01-01T15:00:00Z.
const spec = d({ type: "text", contact: { optedIn: true, lastInboundTimestamp: "1767272400" } }, new Date("2026-01-02T14:59:59Z"));
const specOut = d({ type: "text", contact: { optedIn: true, lastInboundTimestamp: "1767272400" } }, new Date("2026-01-02T15:00:00Z"));
assert.deepEqual(spec, { allowed: true, reason: null });
assert.deepEqual(specOut, { allowed: false, reason: "outside_service_window" });
console.log("ok: spec timestamp boundary");
EOF
